sect1.example:
  Traitement d'une erreur Throwable avec un bloc &finally;


<?php
function inverse($x) {
    return 1/$x;
}

try {
    echo inverse(5) . "\n";
} catch (\DivisionByZeroError $e) {
    echo 'Erreur attrapée : ',  $e->getMessage(), "\n";
} finally {
    echo "Premier finally.\n";
}

try {
    echo inverse(0) . "\n";
} catch (\DivisionByZeroError $e) {
    echo 'Erreur attrapée : ',  $e->getMessage(), "\n";
} finally {
    echo "Second finally.\n";
}

// Poursuite de l'exécution
echo "Bonjour le monde\n";


  &example.outputs.8;


0.2
Premier finally.
Erreur attrapée : Division by zero
Second finally.
Bonjour le monde

  Tous les blocs &finally; sont exécutés


<?php
try {
    try {
        throw new Exception();
    } finally {
        echo "Finally interne\n";
    }
} catch (Exception $e) {
} finally {
    echo "Finally externe\n";
}


  &example.outputs;


Finally interne
Finally externe

sect2.example:
   Interaction entre &return; dans un bloc &finally; et un &return; précédent


<?php
function testReturnTry() {
    try {
        echo 'Dans try', "\n";
        return 'try';
    } finally {
        echo 'Dans finally', "\n";
        return 'finally';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        echo 'Dans catch', "\n";
        return 'catch';
    } finally {
        echo 'Dans finally', "\n";
        return 'finally';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";



   &example.outputs;


Dans try
Dans finally
finally
Dans catch
Dans finally
finally

   Interaction entre le bloc &finally; et &return;


<?php
function testReturnTry() {
    try {
        return 'try';
    } finally {
        echo 'finally ';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        return 'catch';
    } finally {
        echo 'finally ';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";


   &example.outputs;


finally try
finally catch

   Exception dans try et dans finally


<?php

try {
    try {
        throw new Exception(message: 'Troisième', previous: new Exception('Quatrième'));
    } finally {
        throw new Exception(message: 'Première', previous: new Exception('Deuxième'));
    }
} catch (Exception $e) {
    var_dump(
        $e->getMessage(),
        $e->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getPrevious()->getMessage(),
    );
}


   &example.outputs;


string(9) "Première"
string(9) "Deuxième"
string(10) "Troisième"
string(10) "Quatrième"


    Bloc &finally; exécuté lorsqu'une Exception
    a été lancée



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch(\Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch(Exception $e) {
    echo 'catch externe';
}


   &example.outputs.similar;


1
finally
catch externe


    Erreur lors d'un &yield; dans un bloc &finally; lorsqu'une
    Exception a été lancée



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch(\Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
        yield 3;
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch(Exception $e) {
    echo 'catch externe';
}


   &example.outputs.similar;


