   Interaction entre un bloc &finally; et exit appelé dans un bloc &try;


<?php
try {
    echo 'quitter';
    exit(0);
} finally {
    echo 'finally';
}


   &example.outputs;


quitter

   Interaction entre un bloc &finally; et exit appelé dans un bloc &catch;


<?php
try {
    throw new Exception('foo');
} catch (Exception $e) {
    echo 'catch';
    exit(0);
} finally {
    echo 'finally ';
}


   &example.outputs;


catch

   Tous les blocs &finally; sont ignorés lorsque exit est appelé


<?php
try {
    try {
        echo 'quitter';
        exit(0);
    } finally {
        echo 'finally interne ';
    }
} finally {
    echo 'finally externe';
}


   &example.outputs;


quitter

   Ignorer le bloc &finally; externe en appelant exit


<?php
try {
    try {
        echo 'try', "\n";
    } finally {
        echo 'finally interne ';
        exit(0);
    }
} finally {
    echo 'finally externe';
}


   &example.outputs;


try
finally interne
